"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type ChronoScrubFrame = {
  id: string;
  title: string;
  detail?: string;
  at: string;
};

export type ChronoScrubProps = {
  frames: ChronoScrubFrame[];
  className?: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (index: number) => void;
};

/**
 * Scrub an agent / activity timeline — sliding updates the active frame story.
 */
function ChronoScrub({
  frames,
  className,
  value,
  defaultValue = 0,
  onValueChange,
}: ChronoScrubProps) {
  const [internal, setInternal] = React.useState(defaultValue);
  const index = value ?? internal;
  const frame = frames[Math.min(frames.length - 1, Math.max(0, index))];

  const set = (n: number) => {
    if (value === undefined) setInternal(n);
    onValueChange?.(n);
  };

  return (
    <div
      className={cn(
        "w-full max-w-lg space-y-3 rounded-2xl border border-border bg-card p-4 shadow-[var(--shadow-soft)]",
        className,
      )}
    >
      <div className="min-h-[4.5rem]">
        <div className="text-[11px] font-medium uppercase tracking-[0.12em] text-muted-foreground">
          {frame?.at}
        </div>
        <div className="mt-1 text-lg font-semibold tracking-tight">
          {frame?.title}
        </div>
        {frame?.detail ? (
          <p className="mt-1 text-sm text-muted-foreground">{frame.detail}</p>
        ) : null}
      </div>
      <input
        type="range"
        min={0}
        max={Math.max(frames.length - 1, 0)}
        step={1}
        value={index}
        onChange={(e) => set(Number(e.target.value))}
        className="w-full accent-[var(--color-primary)]"
        aria-label="Scrub timeline"
      />
      <div className="flex justify-between gap-2">
        {frames.map((f, i) => (
          <button
            key={f.id}
            type="button"
            onClick={() => set(i)}
            className={cn(
              "h-1.5 flex-1 rounded-full transition-colors",
              i <= index ? "bg-primary" : "bg-muted",
            )}
            aria-label={f.title}
          />
        ))}
      </div>
    </div>
  );
}

export { ChronoScrub };
